import re
import sys

LINE_RE = re.compile(
    r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) ERROR \[([^\]]+)\] (.*)$"
)


def parse_errors(path):
    rows = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            m = LINE_RE.match(line.rstrip("\r\n"))
            if m:
                rows.append({"time": m[1], "module": m[2], "message": m[3]})
    return rows


def format_table(rows):
    def esc(s):
        return s.replace("|", "\\|")

    lines = ["| time | module | message |", "|---|---|---|"]
    for r in rows:
        lines.append(
            f"| {esc(r['time'])} | {esc(r['module'])} | {esc(r['message'])} |"
        )
    return "\n".join(lines)


if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(f"usage: {sys.argv[0]} LOGFILE")
    sys.stdout.reconfigure(encoding="utf-8")
    print(format_table(parse_errors(sys.argv[1])))
EOF
